import {api,escapeHtml as esc} from './catalog.js';
import {loadSession,isAdmin} from './access.js';
import {adminNav,kindNames,bytes} from './multimedia.js';
import {uploadFile} from './upload.js';
const root=document.querySelector('#library-panel');let items=[],artworks=[],page=1,controller,cloudMode=false,cloudMax=100;
async function load(){const params=new URLSearchParams(new FormData(root.querySelector('#library-filter')));params.set('page',page);const data=await api('/resources?'+params);items=data.items;root.querySelector('#library-count').textContent=data.total+' tài nguyên';root.querySelector('#library-rows').innerHTML=items.map(r=>`<tr><td><a href="/tai-nguyen/?id=${encodeURIComponent(r.id)}">${esc(r.title)}</a><br><small>${esc(r.artworks?.map(a=>a.title).join(', ')||'Chưa gắn với tác phẩm')}</small></td><td>${kindNames[r.resourceType]}<br>${esc(r.format?.toUpperCase())}</td><td>${bytes(r.sizeBytes)}</td><td><button class="text-link" data-edit="${esc(r.id)}">Sửa / gắn</button> <button class="danger-link" data-delete="${esc(r.id)}">Xóa</button></td></tr>`).join('');root.querySelector('#library-pagination').innerHTML=`${page>1?'<button data-page="'+(page-1)+'">← Trước</button>':''}<span>Trang ${page}</span>${data.hasMore?'<button data-page="'+(page+1)+'">Sau →</button>':''}`;}
async function render(){artworks=(await api('/artworks')).items;root.innerHTML=adminNav+`<div class="feature-intro"><h2>Mỗi tư liệu, một câu chuyện.</h2><p>Thêm ảnh, audio MP3/WAV tiếng Việt, video, PDF, DOCX và TXT. ${cloudMode?`Kho Cloudinary · video tối đa ${cloudMax} MiB theo cấu hình; hạn mức tài khoản có thể thấp hơn. Tải tiếp cùng tệp trong một giờ, phụ thuộc trạng thái phiên tại kho.`:'Video tối đa 1 GiB; tải tiếp bằng cách chọn lại cùng tệp trong 24 giờ.'}</p></div><div class="feature-toolbar"><label class="button button-dark">+ Tải tài nguyên<input id="library-upload" type="file" multiple accept=".jpg,.jpeg,.png,.webp,.mp4,.webm,.mov,.mp3,.wav,.pdf,.docx,.txt" hidden></label><button class="button button-outline" id="index-images">Cập nhật chỉ mục ảnh</button><button class="button button-outline" id="cleanup">Dọn tệp đã xóa</button></div><p class="subtle-note">Ảnh 8 MiB · audio 64 MiB · PDF/DOCX 20 MiB · TXT 5 MiB. Tệp chưa gắn với hồ sơ chỉ quản trị viên xem được.</p><div id="library-progress" class="upload-progress" role="status"></div><button id="cancel-upload" class="text-link" hidden>Dừng tải (có thể tiếp tục)</button><p id="library-error" class="form-error" role="alert"></p><form id="library-filter" class="filter-form"><label>Tên / nội dung<input name="q" type="search"></label><label>Loại tệp<select name="kind"><option value="">Tất cả</option>${Object.entries(kindNames).map(([key,name])=>`<option value="${key}">${name}</option>`).join('')}</select></label><button class="button button-outline">Lọc tài nguyên</button></form><h3 id="library-count"></h3><div class="table-scroll"><table class="feature-table"><thead><tr><th>Tài nguyên / tác phẩm</th><th>Loại</th><th>Dung lượng</th><th>Thao tác</th></tr></thead><tbody id="library-rows"></tbody></table></div><nav class="pagination" id="library-pagination"></nav><dialog id="resource-dialog" class="management-dialog" aria-labelledby="metadata-title"><div class="dialog-heading"><h2 id="metadata-title">Thông tin tư liệu</h2><button type="button" id="close-resource" aria-label="Đóng">×</button></div><form id="metadata-form" class="metadata-form"></form></dialog>`;root.querySelector('#library-filter').onsubmit=e=>{e.preventDefault();page=1;load().catch(showError);};root.querySelector('#close-resource').onclick=()=>root.querySelector('dialog').close();root.querySelector('#cancel-upload').onclick=()=>controller?.abort();root.querySelector('#library-upload').onchange=async e=>{const input=e.target;controller=new AbortController();input.disabled=true;root.querySelector('#cancel-upload').hidden=false;showError({message:''});try{for(const file of input.files)await uploadFile(file,{signal:controller.signal,onProgress:p=>root.querySelector('#library-progress').textContent=p.name+' · '+p.percent+'%'+(p.validating?' · đang kiểm tra tệp…':'')});root.querySelector('#library-progress').textContent='Đã tải xong. Chọn “Sửa / gắn” để bổ sung thông tin và gắn vào hồ sơ.';await load();}catch(error){showError({message:controller.signal.aborted?'Đã dừng. Chọn lại cùng tệp để tải tiếp.':error.message});}finally{input.disabled=false;input.value='';root.querySelector('#cancel-upload').hidden=true;}};for(const [id,path] of [['index-images','index-images'],['cleanup','cleanup']])root.querySelector('#'+id).onclick=async e=>{const button=e.currentTarget;button.disabled=true;try{const data=await api('/admin/'+path,{method:'POST',signal:AbortSignal.timeout(240000)});root.querySelector('#library-progress').textContent=path==='index-images'?`Đã lập chỉ mục ${data.indexed} ảnh; ${data.failed} lỗi.`:`Đã dọn ${data.removed} tệp; ${data.failed} lỗi cần thử lại.`;}catch(error){showError(error);}finally{button.disabled=false;}};await load();}
function showError(error){root.querySelector('#library-error').textContent=error.message;}
function edit(r){const form=root.querySelector('#metadata-form');form.innerHTML=`<label>Tên tư liệu<input name="title" required maxlength="200" value="${esc(r.title)}"></label><label>Tác giả<input name="author" maxlength="200" value="${esc(r.author)}"></label><label>Chủ đề (phân cách bằng dấu phẩy)<input name="topics" value="${esc(r.topics?.join(', '))}"></label><label>Từ khóa (phân cách bằng dấu phẩy)<input name="tags" value="${esc(r.tags?.join(', '))}"></label><label>Nguồn (URL)<input name="source" type="url" value="${esc(r.source)}"></label><label>Bản quyền<input name="license" maxlength="500" value="${esc(r.license)}"></label><label>Mô tả<textarea name="description" maxlength="5000">${esc(r.description)}</textarea></label>${r.resourceType==='audio'?`<label>Ngôn ngữ<input value="Tiếng Việt (vi-VN)" disabled></label><label>Lời thuyết minh<textarea name="transcript" maxlength="20000">${esc(r.transcript)}</textarea></label>`:''}<label>Gắn thêm với tác phẩm<select name="artifactId"><option value="">Giữ nguyên liên kết</option>${artworks.map(a=>`<option value="${esc(a.id)}">${esc(a.title)}</option>`).join('')}</select></label><p class="subtle-note">Để gỡ liên kết, mở chỉnh sửa hồ sơ tác phẩm và gỡ tư liệu đính kèm.</p><p id="metadata-error" class="form-error" role="alert"></p><button class="button button-dark">Lưu thông tin ↗</button>`;form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button');button.disabled=true;try{const data=Object.fromEntries(new FormData(form));for(const key of ['tags','topics'])data[key]=data[key].split(',').map(v=>v.trim()).filter(Boolean);await api('/resources/'+r.id,{method:'PUT',body:JSON.stringify(data)});if(data.artifactId)await api('/artworks/'+data.artifactId+'/resources',{method:'POST',body:JSON.stringify({resourceId:r.id})});root.querySelector('dialog').close();await load();}catch(error){form.querySelector('#metadata-error').textContent=error.message;}finally{button.disabled=false;}};root.querySelector('dialog').showModal();}
root.addEventListener('click',async e=>{const editButton=e.target.closest('[data-edit]'),del=e.target.closest('[data-delete]'),pg=e.target.closest('[data-page]');if(editButton)edit(items.find(r=>r.id===editButton.dataset.edit));if(pg){page=Number(pg.dataset.page);load().catch(showError);}if(del&&confirm('Xóa tài nguyên khỏi kho? Tài nguyên đang gắn với tác phẩm cần được gỡ liên kết trước.'))try{await api('/resources/'+del.dataset.delete,{method:'DELETE'});await load();}catch(error){showError(error);}});
try{const session=await loadSession();cloudMode=session.uploadStorage==='cloudinary';cloudMax=session.cloudMaxMiB||100;if(!isAdmin(session.user))root.innerHTML='<p>Kho tài nguyên dành cho quản trị viên.</p><a href="/tai-khoan/">Đăng nhập ↗</a>';else await render();}catch(error){root.textContent=error.message;}
